 if(d.type==='support'){if(d.healTimer<=0){d.healTimer=Math.max(.25,1.5-(player.natureSupportRateUpgrade||0)*.15-(player.natureUltBuffTimer>0?.45:0));energy=Math.min(100,energy+1);const healAmount=(player.natureOverdrive>0?5:3)*(d.empowered?1.25:1)*(player.natureUltBuffTimer>0?(player.natureUltHealMult||1):1);const healUnit=(unit,x,y,radius=10)=>{const before=unit.hp;unit.hp=Math.min(unit.maxHp,unit.hp+healAmount);const restored=unit.hp-before;if(restored>0){damageTexts.push({x:x+rand(-4,4),y:y-radius-10,vx:rand(-5,5),vy:-34,life:1.05,max:1.05,text:'+'+Math.round(restored)+' HP',color:'#70e58a',crit:false});burst(x,y-radius*.25,'#70e58a',3);}return restored;};healUnit(player,player.x,player.y,player.r);for(const ally of natureDrones){healUnit(ally,ally.x,ally.y,9);skillFx.push({type:'natureHeal',x:ally.x,y:ally.y,life:.55,max:.55,radius:18,color:'#70e58a'});}player.natureAttackBuff=Math.max(player.natureAttackBuff||0,2.5);skillFx.push({type:'natureHeal',x:player.x,y:player.y,life:.55,max:.55,radius:25,color:'#70e58a'});}}
